     ..write(t.highValue)..write(t.lowValue)..write(t.volumeValue);
  }
  b..write(t.casRefPrice)..write(t.inductiveEquilibriumPrice)
   ..write(t.inductiveEquilibriumQty)..write(t.imbalanceQuantity)
   ..write(t.imbalanceQuantityFromMktOrder);
  return b.toString();
}

