@override
void handleSocketData(Uint8List data) {
  final BroadcastType bType = (super.options as BroadcastOptions).bType;
  final List<dynamic> responses = bType == BroadcastType.regular
      ? dataMapper.map(data)
      : dataMapper.mapTBT(data);
  for (final dynamic event in responses) {
    if (event is QuoteResponse) {
      onBroadcast(event);
    } else if (event is AuthResponse) {
      onLogin(event);
    } else if (event is AuthResponseTBT) {
      onLoginTBT(event);
    } else if (event is SessionResponse) {
      onSessionChanged(event);
    }
  }
}

